SELECT 


    AND r.user_id = #{query.userId}
    AND r.museum_id = #{query.museumId}
    AND r.status = #{query.status}

        AND (r.order_no LIKE CONCAT('%', #{query.keyword}, '%')
        OR r.contact_name LIKE CONCAT('%', #{query.keyword}, '%')
        OR r.contact_phone LIKE CONCAT('%', #{query.keyword}, '%'))

    AND COALESCE(s.visit_date, r.visit_date) >= #{query.dateStart}
    AND COALESCE(s.visit_date, r.visit_date) <= #{query.dateEnd}

ORDER BY r.created_at DESC
